// Actual native Z4c/RWM source admission of independent global clock fixtures.
#include "goal1_native_endpoint.hpp"
#include "goal1_clock_runtime.hpp"
#include "goal1_operator_oracle.hpp"
#include <iostream>
#include <iomanip>
#include <cstdlib>
#include <string>
namespace cs=cubed_sphere;namespace h=z4c::hyperboloidal;
Real Read(){std::string token;if(!(std::cin>>token))throw std::runtime_error("truncated native clock fixture");char*end=nullptr;Real x=std::strtod(token.c_str(),&end);if(!end||*end||!std::isfinite(x))throw std::runtime_error("nonfinite/malformed native fixture");return x;}
Real Error(Real a,Real b){return std::abs(a-b)/std::max({Real(1),std::abs(a),std::abs(b)});}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);std::cout<<std::setprecision(17);int status=0;try{while(std::cin.peek()!=EOF){std::cin>>std::ws;if(std::cin.peek()==EOF)break;int id=Read();Real epsilon=Read(),t=Read(),x[3];for(auto&v:x)v=Read();Real known_radius=Read();h::Z4cJet<Real> empty{};auto u=cs::typed_support::Map<Real>(empty,[](int,Real){return Read();});Real target[22],first[13][3];for(auto&v:target)v=Read();for(auto&r:first)for(auto&v:r)v=Read();
static cs::clock_oracle::Height height48(48),height96(96);Real n[3]{};if(known_radius)for(int d=0;d<3;++d)n[d]=x[d]/known_radius;
auto radial=cs::clock_oracle::Evaluate(known_radius,t,epsilon,height48);auto runtime=cs::clock_oracle::NativeJet(radial,known_radius,n);std::vector<Real>expected;cs::typed_support::Map<Real>(u,[&](int,Real a){expected.push_back(a);return a;});Real state_error=0;cs::typed_support::Map<Real>(runtime,[&](int i,Real a){state_error=std::max(state_error,Error(a,expected[i]));return a;});
auto timerad=radial;for(int k=0;k<10;++k){auto old=radial.f[k];timerad.f[k]=cs::clock_oracle::Series(0);for(int i=0;i<3;++i)for(int j=0;j<3-i;++j)timerad.f[k].a[i][j]=(j+1)*old.a[i][j+1];}auto timejet=cs::clock_oracle::NativeJet(timerad,known_radius,n);Real time_error=0,time_first_error=0;for(int k=0;k<22;++k)time_error=std::max(time_error,Error(cs::operator_oracle::Component(timejet,k).value,target[k]));for(int k=0;k<13;++k){auto q=cs::operator_oracle::Component(timejet,cs::native_endpoint::first_rows[k]);for(int d=0;d<3;++d)time_first_error=std::max(time_first_error,Error(q.d[d],first[k][d]));}u=runtime;
h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);std::array<Real,22>f{};cs::native_endpoint::Result result;bool endpoint=std::abs(p.omega)<1e-14;bool valid=true;Real first_error=0,negative=0;
if(endpoint){result=cs::native_endpoint::Evaluate(u,p,x);valid=result.valid;f=result.rhs;for(int n=0;n<13;++n)for(int d=0;d<3;++d)first_error=std::max(first_error,Error(result.first[n][d],first[n][d]));auto bad=u;bad.trace.value+=.001;negative=cs::native_endpoint::Evaluate(bad,p,x).valid?0:1;}
else{f=cs::typed_support::Core(u,p,rwm::ReferenceConnection(p,x));auto bad=u;for(int d=0;d<3;++d)for(int e=0;e<3;++e)for(int i=0;i<3;++i)for(int j=0;j<3;++j)bad.metric.ddg[d][e][i][j]=0;auto omitted=cs::typed_support::Core(bad,p,rwm::ReferenceConnection(p,x));for(int i=0;i<22;++i)negative=std::max(negative,std::abs(f[i]-omitted[i]));}
Real err=0;for(int i=0;i<22;++i)err=std::max(err,Error(f[i],target[i]));auto con=h::EvolvedConstraints(u,h::CartesianOmega(u,p));auto geometry=h::Geometry(u.metric);Real trace=0;for(int i=0;i<3;++i)for(int j=0;j<3;++j)trace+=geometry.inverse[i][j]*u.a.k[i][j];
std::cout<<"{\"case\":"<<id<<",\"epsilon\":"<<epsilon<<",\"time\":"<<t<<",\"Omega\":"<<p.omega<<",\"endpoint\":"<<(endpoint?"true":"false")<<",\"native_valid\":"<<(valid?"true":"false")<<",\"native22_time_scaled_error\":"<<err<<",\"native13_time_first_scaled_error\":"<<first_error<<",\"H_absolute\":"<<std::abs(con.hamiltonian)<<",\"M_conformal\":"<<sqrt(con.momentum_conformal_norm2)<<",\"M_physical\":"<<sqrt(con.momentum_physical_norm2)<<",\"Z_conformal\":"<<sqrt(con.z4.z_conformal_norm2)<<",\"Z_physical\":"<<sqrt(con.z4.z_physical_norm2)<<",\"det_minus_one\":"<<std::abs(geometry.determinant-1)<<",\"A_trace\":"<<std::abs(trace)<<",\"pole\":"<<result.pole<<",\"tangent\":"<<result.tangent<<",\"second_compatibility\":"<<result.second<<",\"pole_time\":"<<result.pole_time<<",\"nullness_time\":"<<result.nullness_time<<",\"Z_time\":"<<result.z_time<<",\"negative_control_change_or_rejection\":"<<negative<<",\"runtime_native_jet_scaled_error\":"<<state_error<<",\"runtime_native_time_scaled_error\":"<<time_error<<",\"runtime_native_time_first_scaled_error\":"<<time_first_error<<",\"height48\":"<<height48.Value(known_radius)<<",\"height48_96_absolute_difference\":"<<std::abs(height48.Value(known_radius)-height96.Value(known_radius))<<",\"actual_rhs\":[";for(int i=0;i<22;++i)std::cout<<(i?",":"")<<f[i];std::cout<<"]}"<<std::endl;}}
catch(const std::exception&e){std::cerr<<e.what()<<std::endl;status=2;}Kokkos::finalize();return status;}
